public static string JoinUntilLimit(this string[] str, string joiner, int limit) {
    if (limit < 0)
        throw new ArgumentOutOfRangeException(nameof(limit));
    if (str is null)
        throw new ArgumentNullException(nameof(str));
    if (joiner is null)
        throw new ArgumentNullException(nameof(joiner));

    StringBuilder Builder = new(Math.Min(limit, 1024));
    for (int i = 0; i < str.Length; i++) {
        string Value = str[i] ?? string.Empty;
        int SeparatorLength = i == 0 ? 0 : joiner.Length;
        int Remaining = limit - Builder.Length;
        if (SeparatorLength > Remaining || Value.Length > Remaining - SeparatorLength) {
            break;
        }
        if (i > 0) {
            Builder.Append(joiner);
        }
        Builder.Append(Value);
    }
    return Builder.ToString();
}

public readonly bool Equals(TimeOffset other) =>
    StartingTime == other.StartingTime && EndingTime == other.EndingTime;
public override readonly bool Equals(object? obj) => obj is TimeOffset other && Equals(other);
public override readonly int GetHashCode() =>
    unchecked((StartingTime.GetHashCode() * 397) ^ EndingTime.GetHashCode());
public static bool operator ==(TimeOffset a, TimeOffset b) => a.Equals(b);
public static bool operator !=(TimeOffset a, TimeOffset b) => !a.Equals(b);

